-- 045 · capability seed (Wave A) — declares the Wave-A rail capabilities as
-- first-class contracts (docs/12 §4). Shape check per 007: capability_contracts
-- are PLATFORM-LEVEL rows (tenant_id IS NULL — 007's kernel/domain contracts and
-- 011/015 all seed NULL; the demo tenant reads them through the /plugins contract
-- surface, no per-tenant copies needed).
--
-- Guard: WHERE NOT EXISTS with an explicit `x.tenant_id IS NULL` probe — the
-- 011/015 pattern, and REQUIRED here: PG's default NULLS DISTINCT makes
-- `ON CONFLICT (tenant_id, capability_id, version)` silently never match a NULL
-- tenant_id, which would duplicate every platform row on each replay (proven on
-- a scratch database, then fixed to this form). Idempotent by construction:
-- migrate + seed replay + seed replay land exactly one row per capability.
--
-- Every contract carries the Wave-A degradation note: rails are settings-driven
-- and DEGRADE GRACEFULLY when unconfigured — 'logger' provider logs a structured
-- line and the queue still drains; no half-failed sends, no vendor SDK required.
INSERT INTO app.capability_contracts (tenant_id, plugin_id, capability_id, version, kind, contract, enforced)
SELECT NULL, v.plugin_id, v.capability_id, v.version, v.kind, v.contract, v.enforced
FROM (VALUES
  ('rails.sms', 'sms.send', '1.0.0', 'command',
   '{"description":"SMS rail beneath the Communication Orchestrator (docs/DATA-FLOW §20): E.164 recipients, dedup-keyed, settings-driven provider. provider=logger (default) logs a structured line and reports ok; provider=http-generic POSTs to the configured URL with the configured auth header — no vendor SDK. Degrades gracefully when unconfigured: the logger path always works and reports ok with provider=logger.","read_scopes":["comms.read:templates"],"write_scopes":["comms.send:sms"],"side_effects":[{"type":"comms.send","channel":"sms","consent":"verified","policy_ref":"Comms §1.2"}],"policy_refs":["Comms §1.2","TRAI DLT (sender header)"],"audit":{"level":"full","includes":["recipient_tail","dedup_key","provider","ref","error"]},"data_classification":["pii:guardian_contact"],"latency_sla":{"p95_ms":2000,"timeout_ms":8000},"compat":{"kernel":">=1.0 <2.0"},"regions":["IN"],"residency":"IN","degradation":"unconfigured → logger provider, queue still drains"}'::jsonb,
   '{"audit":"full","invariants":["e164_recipients","dedup_key_required","no_secret_in_logs","graceful_unconfigured_degrade"]}'::jsonb),
  ('rails.whatsapp', 'whatsapp.send', '1.0.0', 'command',
   '{"description":"WhatsApp rail beneath the Communication Orchestrator: reuses the comms.whatsapp DLT template registry (settings ->''templates), E.164 recipients, dedup-keyed. provider=logger (default) logs a structured line and reports ok; provider=http-generic POSTs to the configured URL with the configured auth header — no vendor SDK, template rendering stays generic. Degrades gracefully when unconfigured: the logger path always works and reports ok with provider=logger.","read_scopes":["comms.read:templates"],"write_scopes":["comms.send:whatsapp"],"side_effects":[{"type":"comms.send","channel":"whatsapp.template","consent":"verified","policy_ref":"Comms §1.2"}],"policy_refs":["Comms §1.2","TRAI DLT"],"audit":{"level":"full","includes":["template","recipient_tail","dedup_key","provider","ref","error"]},"data_classification":["pii:guardian_contact"],"latency_sla":{"p95_ms":2000,"timeout_ms":8000},"compat":{"kernel":">=1.0 <2.0"},"regions":["IN"],"residency":"IN","degradation":"unconfigured → logger provider, queue still drains"}'::jsonb,
   '{"audit":"full","invariants":["e164_recipients","dedup_key_required","dlt_template_registry_reuse","no_secret_in_logs","graceful_unconfigured_degrade"]}'::jsonb),
  ('payments.razorpay', 'payments.razorpay', '1.0.0', 'command',
   '{"description":"Razorpay order rails (migration 044): gateway orders on open fee obligations via the Razorpay REST orders API (Basic auth, settings key_id/key_secret or RAZORPAY_KEY_ID/RAZORPAY_KEY_SECRET env), signed-webhook facts in plugin_razorpay.order_log. Records facts only; settlement confirm is staff-only through the kernel action spine (Fees §4.2). Degrades gracefully when unconfigured: the orders door answers 503 with operator guidance instead of half-creating gateway state.","read_scopes":["money.read:obligations"],"write_scopes":["plugin_razorpay.orders","plugin_razorpay.webhooks"],"event_inputs":["fee.due@>=1.0"],"event_outputs":["razorpay.order.created.v1","payment.captured.v1","payment.failed.v1"],"side_effects":[{"type":"payment.order.create","approval":"never","policy_ref":"Fees §4.2"},{"type":"ledger.post","approval":"required","policy_ref":"Fees §4.2","note":"settle only via kernel fee.payment.settle (staff confirm)"}],"policy_refs":["Fees §4.2"],"audit":{"level":"full","includes":["actor","obligation","gateway_order_ref","webhook_verified"]},"data_classification":["financial","pii:guardian_contact"],"idempotency":{"key":"webhook.id","window":"24h"},"compat":{"kernel":">=1.0 <2.0"},"regions":["IN"],"residency":"IN","degradation":"unconfigured → orders door 503, webhook fail-closed 403; no partial gateway state"}'::jsonb,
   '{"audit":"full","invariants":["never_auto_moves_money","settle_kernel_only","webhook_signature_required","gateway_ref_honesty","graceful_unconfigured_degrade"]}'::jsonb),
  ('files.store', 'files.store', '1.0.0', 'capability',
   '{"description":"File/document storage surface for homework attachments, exam papers, clinic records and admission documents. Contract declared Wave A; implementation lands with the storage lane. Degrades gracefully: capability declared but unconfigured consumers must treat file features as optional and never block core flows.","read_scopes":["artifact.read:own"],"write_scopes":["artifact.put"],"side_effects":[{"type":"artifact.put","approval":"never","policy_ref":"Platform §5.2"}],"policy_refs":["Platform §5.2"],"audit":{"level":"digest","includes":["content_hash","provenance"]},"data_classification":["pii:documents"],"compat":{"kernel":">=1.0 <2.0"},"regions":["IN"],"residency":"IN","degradation":"declared ahead of implementation — consumers must treat as optional"}'::jsonb,
   '{"audit":"digest","invariants":["hash_addressed","provenance_linked","graceful_unconfigured_degrade"]}'::jsonb),
  ('library', 'library', '1.0.0', 'capability',
   '{"description":"Library management surface: catalogue, issue/return, overdue notices riding the Communication Orchestrator. Contract declared Wave A; implementation lands with the library lane. Degrades gracefully: capability declared but unconfigured consumers must treat library features as optional and never block core flows.","read_scopes":["library.read"],"write_scopes":["library.issue","library.return"],"side_effects":[{"type":"comms.send","channel":"whatsapp.template","consent":"verified","policy_ref":"Comms §1.2"}],"policy_refs":["Comms §1.2"],"audit":{"level":"full","includes":["actor","copy","borrower","action"]},"data_classification":["internal"],"compat":{"kernel":">=1.0 <2.0"},"regions":["IN"],"residency":"IN","degradation":"declared ahead of implementation — consumers must treat as optional"}'::jsonb,
   '{"audit":"full","invariants":["orchestrator_notice_only","graceful_unconfigured_degrade"]}'::jsonb),
  ('people.import', 'people.import', '1.0.0', 'command',
   '{"description":"Bulk people import surface (students/guardians/staff from migration sources, CSV/Excel): staged import with dry-run diff, deterministic mapping, audit per batch. Contract declared Wave A; implementation lands with the import lane. Degrades gracefully: capability declared but unconfigured consumers must treat bulk import as optional and never block core flows.","read_scopes":["students.read","guardians.read"],"write_scopes":["people.import.batch"],"side_effects":[{"type":"people.import","approval":"required","policy_ref":"Platform §3.1","note":"batch application is owner-gated"}],"policy_refs":["Platform §3.1"],"audit":{"level":"full","includes":["actor","batch_digest","counts","rejections"]},"data_classification":["pii:student_records","pii:guardian_contact"],"compat":{"kernel":">=1.0 <2.0"},"regions":["IN"],"residency":"IN","degradation":"declared ahead of implementation — consumers must treat as optional"}'::jsonb,
   '{"audit":"full","invariants":["owner_gated_apply","batch_digest_audited","graceful_unconfigured_degrade"]}'::jsonb)
) AS v(plugin_id, capability_id, version, kind, contract, enforced)
WHERE NOT EXISTS (
  SELECT 1 FROM app.capability_contracts x
  WHERE x.tenant_id IS NULL AND x.capability_id = v.capability_id AND x.version = v.version);
